head.script:
scwin.screenId = "jldfil25910";

///////// 1. 변수 및 선언 영역 /////////

scwin.ex = $c.util.getComponent('ex');

scwin.filebox = $c.util.getComponent('filebox');

scwin.modifiyDate = "N";

scwin.delck = "N";


///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    let __pc = $c.util.getComponent('dma_pageContext');
    if (!__pc || !__pc.set || !__pc.get) { return; }
    if (!__pc.get("sysYear")) { __pc.set("sysYear", $c.date.getServerDateTime("yyyy")); }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = function () {
    let __attrReals = [{ childId: "txa_shrhdNmlistClsBasddContn", attr: "label", fn: function () { return String($c.data.readValue("dma_dividendDate", "shrhdNmlistClsBasddContn", { silent: true })); } },
        { childId: "txa_proftDivRemk", attr: "label", fn: function () { return String($c.data.readValue("dma_dividendDate", "proftDivRemk", { silent: true })); } }];
    $c.util.applyAttrReals(__attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "if_attachFileNm", fn: function(){ return (!(String(($c.data.readValue("dma_dividendDate", "attachFileNm", { label: "dividendDate.attachFileNm" })) == null ? '' : ($c.data.readValue("dma_dividendDate", "attachFileNm", { label: "dividendDate.attachFileNm" }))).length === 0)); } }, { id: "if_checkModifiyDate", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y'); } }, { id: "tr_63", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y'); } }, { id: "tr_70", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y'); } }, { id: "tr_73", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y'); } }, { id: "tr_78", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y'); } }, { id: "tr_83", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y'); } }, { id: "if_checkModifiyDate_2", fn: function(){ return ($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'N' || $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) !== 'Y'); } }, { id: "tr_98", fn: function(){ return ($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'N' || $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) !== 'Y'); } }, { id: "tr_105", fn: function(){ return ($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'N' || $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) !== 'Y'); } }, { id: "tr_108", fn: function(){ return ($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'N' || $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) !== 'Y'); } }, { id: "tr_112", fn: function(){ return ($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'N' || $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) !== 'Y'); } }, { id: "tr_116", fn: function(){ return ($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'N' || $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) !== 'Y'); } }, { id: "registerBtn", fn: function(){ return ((String(($c.data.readValue("dma_dividendDate", "bzProcsNo", { label: "dividendDate.bzProcsNo" })) == null ? '' : ($c.data.readValue("dma_dividendDate", "bzProcsNo", { label: "dividendDate.bzProcsNo" }))).length === 0)); } }, { id: "registerBtn_2", fn: function(){ return (!(String(($c.data.readValue("dma_dividendDate", "bzProcsNo", { label: "dividendDate.bzProcsNo" })) == null ? '' : ($c.data.readValue("dma_dividendDate", "bzProcsNo", { label: "dividendDate.bzProcsNo" }))).length === 0)); } }, { id: "registerBtn", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y' && $c.data.readValue("dma_dividendDate", "basYy", { label: "dividendDate.basYy" }) === $c.data.readValue("sysYear", "toString", { label: "sysYear.toString" })()); } }, { id: "registerBtn_2", fn: function(){ return (($c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'Y' ||$c.data.readValue("dma_pageContext", "checkModifiyDate", { ctx: true, label: "checkModifiyDate" }) === 'U') && $c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) === 'Y' && $c.data.readValue("dma_dividendDate", "basYy", { label: "dividendDate.basYy" }) === $c.data.readValue("sysYear", "toString", { label: "sysYear.toString" })()); } }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = function () {
    let __rowCopies = [{ childId: "__rb2", fn: function () { return String($c.data.readValue("dma_dividendDate", "basYy", { silent: true })) + " 년"; } },
        { childId: "__rb3", fn: function () { return String($c.data.readValue("dma_dividendDate", "acntclsMm", { silent: true })) + " 월"; } }];
    $c.data.copyRows(__rowCopies);
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        scwin.basDRadio();
        $("input[name='divBasDdYn']").change(function() {
                let yn = this.value;
                if (yn === "Y") {
                    $c.util.getComponent('cal_divBasDd').setValue("");
                    $(".ui-datepicker-trigger").click();
                    /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                } else {
                    $c.util.getComponent('cal_divBasDd').setValue("-");
                    /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25910.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

scwin.upd_attachFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile"]');

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.result = undefined; scwin.modifiyDate = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25910.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

