/**
 * @method
 * @name scwin.fn_setLength
 * @author Inswave
 * @date 2026. 09. 06
 * @param obj tdName maxLength
 * @returns
 * @hidden N
*/
scwin.fn_setLength = function (obj, tdName, maxLength) {
    let strLength = scwin.fn_calBytes(obj);
    ($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setValue) ? $c.util.getComponent(tdName).setValue("(" + strLength + "/" + maxLength + ")") : (($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setText) ? $c.util.getComponent(tdName).setText("(" + strLength + "/" + maxLength + ")") : console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + tdName));
};


/**
 * @method
 * @name scwin.fn_estimateCounter
 * @author Inswave
 * @date 2026. 09. 06
 * @param obj maxLength
 * @returns
 * @hidden N
*/
scwin.fn_estimateCounter = async function (obj, maxLength) {
    if (scwin.fn_calBytes(obj.value) > maxLength) {
        await $c.win.alert('한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};


/**
 * @method
 * @name scwin.fn_calBytes
 * @author Inswave
 * @date 2026. 09. 06
 * @param str
 * @returns
 * @hidden N
*/
scwin.fn_calBytes = function (str) {
    let tcount = 0;
    let tmpStr = new String(str);
    let temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};


